        "f1762558ad1c41c8992f1f3fa36e8afa": {
          "id": "f1762558ad1c41c8992f1f3fa36e8afa",
          "name": "Get User Active Badges",
          "script": "(function execute() {\n\n    vaVars.user_badge_count = 0;\n    var identityId = vaInputs.user_sys_id;    \n    var badgeAction = \"replace\" //\n   //TODO - DO not replace mobile creds\n    var baseURL = gs.getProperty('glide.servlet.uri');\n    var images = {};\n    images['PERMANENT_BADGE'] = baseURL + '/x_aleen_aia_skills.permanentbadge.png';\n    images['TEMP_BADGE'] = baseURL + '/x_aleen_aia_skills.visitorbadge.png';\n    images['MOBILE_CREDENTIAL'] = baseURL + '/x_aleen_aia_skills.digitalbadge.png';\n\n    var badgeArray = [];\n    var badgeGr = new GlideRecordSecure('x_aleen_snguardian_identity_asset'); \n    badgeGr.addQuery('identity', identityId);\n    badgeGr.addNotNullQuery('status');\n    badgeGr.addQuery('status.code', 'ACTIVE');\n    badgeGr.addQuery('is_deleted',false);\n    badgeGr.addQuery('asset.type.code','!=','MOBILE_CREDENTIAL');\n    badgeGr.query();\n    while (badgeGr.next()) {\n        badgeArray.push({\n            'name': badgeGr.getDisplayValue(\"asset.serial\")+\"(\"+badgeGr.getDisplayValue(\"identifier\") +\")\",\n            'value':badgeGr.getValue(\"sys_id\"),\n            'description':badgeGr.getDisplayValue(\"identity.full_name\") +\" - \" +badgeGr.getDisplayValue(\"valid_to\")+\" - \" +badgeGr.getDisplayValue(\"status.name\"),\n            'body': images[badgeGr.getDisplayValue(\"asset.type.code\")]\n        });\n    }\n    vaVars.user_badges_list = JSON.stringify(badgeArray);\n    if(badgeArray.length >0){\n       vaVars.user_badge_count = badgeArray.length;\n    }\n})();",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
