          "inputs": [
            {
              "itemId": "e52a3222159845bbba78533b52f60b7c",
              "displayName": "Display User Active Badges",
              "name": "display_user_active_badges",
              "description": "Ask user to select one of displayed badges to take further action \nASK ONE LINE QUESTION as Please select badge to be replaced.",
              "discoverable": true,
              "dynamicDescription": {
