                }
              ],
              "mode": "",
              "script": "(function execute() {\n     var options = [];\n     var items = JSON.parse(vaVars.user_badges_list|| '[]');\n    if (items.length === 0) {\n        options.push({\n            name: 'No Badge',\n            value: 'none',\n            description: 'No badge found',\n            body: 'https://somehost/somepath/somepic1.jpg'\n        });\n    } else {\n        items.forEach(function(it) {\n            options.push({\n                name: it.name || '',\n                value: it.value || '',\n                description: it.description || '',\n                body: it.body || ''\n            });\n        });\n    }\nreturn options;\n})();\n",
