        "52afc7f40a0e461ab30b407b69cbda85": {
          "id": "52afc7f40a0e461ab30b407b69cbda85",
          "name": "Get Badge Action Config",
          "script": "(function execute() {\n    //GETTING USER LOCATION , USER TYPE\n    var idenlocationGr = new GlideRecordSecure('x_aleen_snguardian_identity_location')\n    idenlocationGr.addQuery('identity',vaInputs.user_sys_id);\n    idenlocationGr.query();\n    var location = \"\";\n    if(idenlocationGr.next()){\n        location = idenlocationGr.location;\n        vaVars.user_location = location;\n        vaVars.user_type = idenlocationGr.identity.type;\n    }\n\n    //BADGE TYPE BASED ON SELECTED BADGE \n    vaVars.badge_to_replace = vaInputs.display_user_active_badges;\n    var idenAssetGr = new GlideRecordSecure('x_aleen_snguardian_identity_asset');\n    idenAssetGr.addQuery('sys_id',vaVars.badge_to_replace);\n    idenAssetGr.query();\n    if(idenAssetGr.next()){\n        vaVars.badge_type = idenAssetGr.getDisplayValue('asset.type.code'); //asset type code\n        vaVars.badge_system = idenAssetGr.asset.system   // system sys_id\n    }\n    \n    vaVars.badge_action = \"replace\"\n    var inputs = {};\n    inputs['u_location'] = vaVars.user_location; // Reference, Sys ID of the record \n    inputs['u_employee_type'] = vaVars.user_type; // Reference, Sys ID of the record \n    inputs['u_badge_type'] = vaVars.badge_type; // String \n    inputs['u_badge_action'] = vaVars.badge_action; // String \n    \n    var dt = new sn_dt.DecisionTableAPI();\n    var response = dt.getDecision('0d37c78833843650bf1221382e5c7bc7', inputs);\n\n    var result_elements = response.result_elements;\n    vaVars.dt_res_u_auto_badge_allocation = result_elements.u_auto_badge_allocation.getValue(); // True/False\n    vaVars.dt_res_u_create_request = result_elements.u_create_request.getValue(); // True/False\n    vaVars.dt_res_u_def_valid_from = result_elements.u_def_valid_from.getValue(); // True/False\n    vaVars.dt_res_u_def_valid_to = result_elements.u_def_valid_to.getValue(); // Duration\n    vaVars.dt_res_u_def_access = result_elements.u_def_access.getValue(); // True/False\n    vaVars.dt_res_u_copy_access = result_elements.u_copy_access.getValue() ;   //True/False\n    vaVars.dt_res_u_deactivate_old_badge = result_elements.u_deactivate_old_badge.getValue();  //True/False\n   \n    vaVars.new_asset_id = \"\";   \n    if(vaVars.dt_res_u_auto_badge_allocation == \"1\" || vaVars.dt_res_u_auto_badge_allocation == 1){\n        var assetGr = new GlideRecordSecure('x_aleen_snguardian_asset');\n        assetGr.addQuery('type.code',vaVars.badge_type);   \n        assetGr.addQuery('system',vaVars.badge_system);   \n        assetGr.addQuery('status.code',\"UNASSIGNED\");\n        assetGr.query();\n        if(assetGr.next()){\n            vaVars.new_asset_id = assetGr.getUniqueValue();  \n        }\n    }\n\n    if(vaVars.dt_res_u_def_valid_from == \"1\"){\n        vaVars.badge_valid_from_cal = new GlideDateTime().getDisplayValue();\n    }else{\n        vaVars.badge_valid_from_cal = \"\";\n    }\n  \n    if(\"1970-01-01 00:00:00\" != vaVars.dt_res_u_def_valid_to && \"\" != vaVars.dt_res_u_def_valid_to){\n        vaVars.badge_valid_to_calc = new x_aleen_snguardian.TimeZoneUtil().getDurationDifference(vaVars.dt_res_u_def_valid_to, \"add\");\n    }else{\n        vaVars.badge_valid_to_calc = \"\";\n    }\n\n    //ASK USER INPUT :: IF MANUAL, valid from ==0 , valid to ==0\n    if( vaVars.dt_res_u_create_request == \"0\"){\n       vaVars.submission_mode = \"direct\";\n    }else{\n       // vaVars.submission_mode = \"request\";\n        vaVars.submission_mode = \"direct\";\n    }\n    \n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
